@dataclass(frozen=True)
class Reservation:
    request_id: str
    item: str
    quantity: int


class Inventory:
    def __init__(self, total_stock):
        if type(total_stock) is not int:
            raise TypeError("total stock must be an integer")
        if total_stock < 0:
            raise ValueError("total stock cannot be negative")
        self.total_stock = total_stock
        self.reserved = 0
        self.requests = {}

    @property
    def available(self):
        return self.total_stock - self.reserved

    @staticmethod
    def _validate_text(name, value):
        if type(value) is not str:
            raise TypeError(f"{name} must be a string")
        if value == "":
            raise ValueError(f"{name} cannot be empty")

    @classmethod
    def _validate_request(cls, request_id, item, quantity, simulate_unknown):
        cls._validate_text("request ID", request_id)
        cls._validate_text("item", item)
        if type(quantity) is not int:
            raise TypeError("quantity must be an integer and not bool")
        if quantity <= 0:
            raise ValueError("quantity must be positive")
        if type(simulate_unknown) is not bool:
            raise TypeError("simulate_unknown must be bool")

    @staticmethod
    def _payload(item, quantity):
        return item, quantity

    def reserve(self, request_id, item, quantity, simulate_unknown=False):
        self._validate_request(request_id, item, quantity, simulate_unknown)
        payload = self._payload(item, quantity)
        prior = self.requests.get(request_id)
        if prior is not None:
            if self._payload(prior.item, prior.quantity) != payload:
                raise RequestConflict("request ID is bound to a different payload")
            return prior
        if quantity > self.available:
            raise ValueError("quantity is unavailable")
        reservation = Reservation(request_id, item, quantity)
        self.reserved += quantity
        self.requests[request_id] = reservation
        if simulate_unknown:
            raise UnknownOutcome("the caller did not receive the result")
        return reservation

    def replay(self, request_id, item, quantity):
        return self.reserve(request_id, item, quantity)

    def snapshot(self):
        return self.reserved, dict(self.requests)

    def restore(self, snapshot):
        reserved, requests = snapshot
        self.reserved = reserved
        self.requests = dict(requests)

