import argparse
import hashlib
import json
import pathlib
import subprocess
import sys


BOUND_FILES = [
    "fixture.json",
    "inventory.py",
    "test_inventory.py",
]


def sha256_file(path):
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        for block in iter(lambda: handle.read(65536), b""):
            digest.update(block)
    return digest.hexdigest()


def current_hashes():
    return {path: sha256_file(path) for path in BOUND_FILES}


def run_test():
    command = [sys.executable, "-m", "unittest", "-v", "test_inventory.py"]
    completed = subprocess.run(command, text=True, capture_output=True)
    return {
        "command": command,
        "exitCode": completed.returncode,
        "observed": "PASS" if completed.returncode == 0 else "FAIL",
        "stdout": completed.stdout,
        "stderr": completed.stderr,
    }


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--record", default="evidence.json")
    parser.add_argument("--compare")
    args = parser.parse_args()

    files = current_hashes()
    result = run_test()
    record = {
        "requirement": (
            "conservation, strict validated payload binding, unknown-outcome "
            "replay, denial without mutation, and snapshot recovery"
        ),
        "files": files,
        "test": {
            "expected": "7 unittest methods pass and the subprocess exits 0",
            "result": result,
        },
        "stale": False,
    }

    if args.compare:
        old = json.loads(pathlib.Path(args.compare).read_text(encoding="utf-8"))
        record["stale"] = old.get("files") != files
        record["comparedWith"] = args.compare

    pathlib.Path(args.record).write_text(
        json.dumps(record, indent=2) + "\n",
        encoding="utf-8",
    )
    print(
        json.dumps(
            {
                "record": args.record,
                "stale": record["stale"],
                "observed": result["observed"],
                "testExitCode": result["exitCode"],
            }
        )
    )
    return result["exitCode"]


if __name__ == "__main__":
    raise SystemExit(main())

